    OperatorState state = mock(OperatorState.class);
    Map<OperatorID, OperatorState> operatorStates = new HashMap<>();
    operatorStates.put(new OperatorID(), state);
    for (JobStatus status : terminalStates) {
        Mockito.reset(state);
        // Keep
        CheckpointProperties props = new CheckpointProperties(false, true, false, false, false, false, false, false);
        CompletedCheckpoint checkpoint = new CompletedCheckpoint(new JobID(), 0, 0, 1, new HashMap<>(operatorStates), Collections.<MasterState>emptyList(), props, new FileStateHandle(new Path(file.toURI()), file.length()), externalPath);
        SharedStateRegistry sharedStateRegistry = new SharedStateRegistry();
        checkpoint.registerSharedStatesAfterRestored(sharedStateRegistry);
        checkpoint.discardOnShutdown(status);
        verify(state, times(0)).discardState();
        assertEquals(true, file.exists());
        // Discard
        props = new CheckpointProperties(false, false, false, true, true, true, true, true);
        checkpoint = new CompletedCheckpoint(new JobID(), 0, 0, 1, new HashMap<>(operatorStates), Collections.<MasterState>emptyList(), props, null, null);
        checkpoint.discardOnShutdown(status);
        verify(state, times(1)).discardState();
    }
}

