    TestingLeaderElectionService testingLeaderElectionService = new TestingLeaderElectionService() {

        @Override
        public void confirmLeaderSessionID(UUID leaderSessionId) {
            super.confirmLeaderSessionID(leaderSessionId);
            leaderSessionIdFuture.complete(leaderSessionId);
        }
    };
    haServices.setSubmittedJobGraphStore(mockSubmittedJobGraphStore);
    haServices.setDispatcherLeaderElectionService(testingLeaderElectionService);
    HeartbeatServices heartbeatServices = new HeartbeatServices(1000L, 1000L);
    final JobID jobId = new JobID();
    final TestingDispatcher dispatcher = new TestingDispatcher(rpcService, Dispatcher.DISPATCHER_NAME + '_' + name.getMethodName(), new Configuration(), haServices, mock(ResourceManagerGateway.class), mock(BlobServer.class), heartbeatServices, mock(MetricRegistryImpl.class), fatalErrorHandler, mock(JobManagerRunner.class), jobId);
    try {
        dispatcher.start();
