        }
    };
    ResultPartitionManager manager = mock(ResultPartitionManager.class);
    when(manager.createSubpartitionView(any(ResultPartitionID.class), anyInt(), any(BufferAvailabilityListener.class))).thenAnswer(viewCreator);
    return manager;
}

