    /* 12 */
    createBarrier(1, 2), // some more buffers
    /* 13 */
    createBuffer(0), createBuffer(1), createBuffer(2), // complete next checkpoint regularly
    /* 16 */
    createBarrier(2, 0), createBarrier(2, 2), // some more buffers
