    ListState<Tuple2<TimeWindow, TimeWindow>> mockState = mock(ListState.class);
    MergingWindowSet<TimeWindow> windowSet = new MergingWindowSet<>(EventTimeSessionWindows.withGap(Time.milliseconds(3)), mockState);
